const q = $('ML Busca Pergunta').first().json;
const lista = $input.first().json.payload || [];
const conv = lista.find(c => String(c.custom_attributes?.ml_question_id) === String(q.id)) || null;

let acao = 'ignorar';
if (!conv && q.status === 'UNANSWERED') acao = 'criar';
else if (conv && conv.status !== 'resolved' && q.status !== 'UNANSWERED') acao = 'fechar';

return [{ json: { acao, pergunta: q, conversation_id: conv ? conv.id : null } }];

const cfg = $('Config').first().json;
const p = $('Decide Pergunta').first().json.pergunta;
const item = $('ML Busca Anuncio').first().json || {};
const user = $('ML Busca Comprador').first().json || {};

const brl = v => v == null ? '-' : Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const nota = [
  '❓ Pergunta do Mercado Livre',
  `📦 ${item.title || p.item_id}`,
  `💰 ${brl(item.price)} | Estoque: ${item.available_quantity ?? '-'} | Status: ${item.status ?? '-'}`,
  item.permalink ? `🔗 ${item.permalink}` : null,
  '',
  'Responda nesta conversa: a resposta vai para o ML e a conversa é resolvida automaticamente.',
  'Atenção: o ML aceita apenas UMA resposta por pergunta (sem telefone, e-mail ou links externos).',
].filter(x => x !== null).join('\n');

return [{ json: {
  tipo: 'pergunta',
  buyer_id: String(p.from.id),
  nome: user.nickname || `Comprador ML ${p.from.id}`,
  inbox_id: Number(cfg.inbox_perguntas),
  nota,
} }];

// client_message_id torna a criação idempotente: reenvio do ML não duplica.
const cmid = s => ('ml_' + String(s)).replace(/[^a-zA-Z0-9_.:-]/g, '').slice(0, 128);
const TEXTO_ANEXO = 'Segue anexo.'; // texto usado quando o agente envia só anexo
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, '');
const attrs = m => { try { return typeof m.content_attributes === 'string' ? JSON.parse(m.content_attributes) : (m.content_attributes || {}); } catch (e) { return {}; } };
// true quando um agente já escreveu este mesmo texto no Chatwoot (mensagem que saiu do Chatwoot para o ML)
function jaExisteNoChatwoot(resp, texto) {
  const lista = Array.isArray(resp?.payload) ? resp.payload : [];
  const alvo = norm(texto);
  if (!alvo) return false;
  const limite = Date.now() / 1000 - 24 * 3600;
  return lista.some(m => (m.message_type === 1 || m.message_type === 'outgoing') && !m.private
    && !attrs(m).origem_ml && norm(m.content || TEXTO_ANEXO) === alvo && Number(m.created_at || 0) >= limite);
}

const q = $('Decide Pergunta').first().json.pergunta;
let out;
if (q.status === 'ANSWERED') {
  const resposta = q.answer?.text || '';
  // Se a resposta saiu do Chatwoot, ela já está na conversa: só resolve.
  out = jaExisteNoChatwoot($input.first().json, resposta)
    ? { postar: false }
    : { postar: true, content: '🛒 Respondido pelo painel do ML\n' + resposta, private: false, client_message_id: cmid('q_answer_' + q.id) };
} else {
  out = { postar: true, content: `🗑️ Pergunta ficou com status ${q.status} no Mercado Livre.`, private: true,
          client_message_id: cmid('q_status_' + q.id + '_' + q.status) };
}
return [{ json: out }];

const r = $input.first().json;
const m = Array.isArray(r.messages) ? r.messages[0] : r;
const seller = Number($('Config').first().json.seller_id);
const recursos = m.message_resources || [];
const pack = recursos.find(x => x.name === 'packs') || recursos.find(x => x.name === 'orders') || recursos[0] || {};
const de = Number(m.from?.user_id);
const para = Number(m.to?.user_id);
const texto = typeof m.text === 'string' ? m.text : (m.text?.plain || '');
const anexos = (m.message_attachments || [])
  .map(a => ({ id: a.filename, nome: a.original_filename || a.filename, mime: a.type || '' }))
  .filter(a => a.id);

return [{ json: {
  message_id: m.id,
  pack_id: pack.id ? String(pack.id) : '',
  buyer_id: de === seller ? para : de,
  do_vendedor: de === seller,
  cmid: ('ml_msg_' + String(m.id)).replace(/[^a-zA-Z0-9_.:-]/g, '').slice(0, 120),
  texto: texto.trim(),
  anexos,
} }];

const m = $('Normaliza Mensagem').first().json;
const lista = $input.first().json.payload || [];
const conv = lista.find(c => String(c.custom_attributes?.ml_pack_id) === String(m.pack_id)) || null;
let acao = 'criar';
if (conv) acao = m.do_vendedor ? 'espelhar' : 'adicionar';
return [{ json: { acao, conversation_id: conv ? conv.id : null } }];

// client_message_id torna a criação idempotente: reenvio do ML não duplica.
const cmid = s => ('ml_' + String(s)).replace(/[^a-zA-Z0-9_.:-]/g, '').slice(0, 128);
const TEXTO_ANEXO = 'Segue anexo.'; // texto usado quando o agente envia só anexo
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, '');
const attrs = m => { try { return typeof m.content_attributes === 'string' ? JSON.parse(m.content_attributes) : (m.content_attributes || {}); } catch (e) { return {}; } };
// true quando um agente já escreveu este mesmo texto no Chatwoot (mensagem que saiu do Chatwoot para o ML)
function jaExisteNoChatwoot(resp, texto) {
  const lista = Array.isArray(resp?.payload) ? resp.payload : [];
  const alvo = norm(texto);
  if (!alvo) return false;
  const limite = Date.now() / 1000 - 24 * 3600;
  return lista.some(m => (m.message_type === 1 || m.message_type === 'outgoing') && !m.private
    && !attrs(m).origem_ml && norm(m.content || TEXTO_ANEXO) === alvo && Number(m.created_at || 0) >= limite);
}

const m = $('Normaliza Mensagem').first().json;
// Mensagem enviada pelo Chatwoot volta como notificação do ML: já está na conversa (com os anexos), ignora.
if (jaExisteNoChatwoot($input.first().json, m.texto)) return [];
return [{ json: { ok: true } }];

const cfg = $('Config').first().json;
const m = $('Normaliza Mensagem').first().json;
const o = $('ML Busca Pedido').first().json || {};

const brl = v => v == null ? '-' : Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const itens = (o.order_items || []).map(i => `• ${i.quantity}x ${i.item?.title}`).join('\n');
const nota = [
  '💬 Mensagem pós-venda do Mercado Livre',
  `🧾 Pack/Pedido: ${m.pack_id}`,
  o.id ? `Status: ${o.status} | Total: ${brl(o.total_amount)}` : null,
  itens || null,
  o.shipping?.id ? `🚚 Envio: ${o.shipping.id}` : null,
  '',
  'Mensagens para o ML têm limite de 350 caracteres. Anexos aceitos: JPG, PNG, PDF e TXT. A conversa fica aberta.',
].filter(x => x !== null).join('\n');

return [{ json: {
  tipo: 'mensagem',
  buyer_id: String(m.buyer_id),
  nome: o.buyer?.nickname || `Comprador ML ${m.buyer_id}`,
  inbox_id: Number(cfg.inbox_mensagens),
  nota,
} }];

let d;
for (const n of ['Contato Pergunta', 'Contato Mensagem']) {
  try { d = $(n).first().json; if (d) break; } catch (e) {}
}
const ident = `ml_${d.buyer_id}`;
const lista = $input.first().json.payload || [];
const c = lista.find(x => x.identifier === ident);
return [{ json: { ...d, identifier: ident, contact_id: c ? c.id : null } }];

const d = $('Contato Existe').first().json;
const j = $input.first().json;
const contact_id = d.contact_id ?? j.payload?.contact?.id ?? j.payload?.id ?? j.id;
return [{ json: { ...d, contact_id } }];

const m = $('Normaliza Mensagem').first().json;
let conversation_id = $('Decide Mensagem').first().json.conversation_id;
if (!conversation_id) conversation_id = $('CW Criar Conversa Mensagem').first().json.id;
const vend = m.do_vendedor;
return [{ json: {
  conversation_id,
  message_type: vend ? 'outgoing' : 'incoming',
  prefixo: vend ? '🛒 Enviado pelo painel do ML' : '',
  texto: m.texto,
  cmid: m.cmid,
  anexos: m.anexos || [],
} }];

const p = $('Prepara Envio').first().json;
return (p.anexos || []).map((a, i) => ({ json: {
  ...a,
  conversation_id: p.conversation_id,
  message_type: p.message_type,
  content: p.prefixo ? '🛒 Anexo enviado pelo painel do ML' : '',
  cmid: `${p.cmid}_a${i}`,
} }));

const lista = $('Lista Anexos ML').all();
return $input.all().map((it, i) => {
  const a = lista[i]?.json || {};
  const bin = it.binary?.data;
  const out = { json: { ...a, baixou: !!bin } };
  if (bin) {
    bin.fileName = a.nome || bin.fileName;
    if (a.mime) bin.mimeType = a.mime;
    out.binary = { data: bin };
  }
  return out;
});
